(()=>{class SmartAdSensePopup{constructor(){this.isInitialized=!1,this.updateInterval=null,this.config={autoStart:!0,stealthMode:!0,personalityType:"auto",maxPostsPerSession:5,readingTimeRange:{min:2,max:5}},this.init()}async init(){try{await this.loadConfig(),this.setupEventListeners(),this.initializeUI(),this.startRealTimeUpdates(),this.isInitialized=!0}catch(t){this.showError("Failed to initialize popup")}}async loadConfig(){try{const t=await chrome.runtime.sendMessage({action:"getConfig"});t&&t.config&&(this.config={...this.config,...t.config})}catch(t){}}setupEventListeners(){document.getElementById("autoStartToggle").addEventListener("change",t=>{this.config.autoStart=t.target.checked,this.saveConfig()}),document.getElementById("stealthModeToggle").addEventListener("change",t=>{this.config.stealthMode=t.target.checked,this.saveConfig()}),document.getElementById("personalitySelect").addEventListener("change",t=>{this.config.personalityType=t.target.value,this.saveConfig()}),document.getElementById("maxPostsInput").addEventListener("change",t=>{this.config.maxPostsPerSession=parseInt(t.target.value),this.saveConfig()}),document.getElementById("readingTimeMin").addEventListener("change",t=>{this.config.readingTimeRange.min=parseInt(t.target.value),this.saveConfig()}),document.getElementById("readingTimeMax").addEventListener("change",t=>{this.config.readingTimeRange.max=parseInt(t.target.value),this.saveConfig()}),document.getElementById("startBtn").addEventListener("click",()=>{this.startAutomation()}),document.getElementById("stopBtn").addEventListener("click",()=>{this.stopAutomation()}),document.getElementById("exportBtn").addEventListener("click",()=>{this.exportData()}),document.getElementById("resetBtn").addEventListener("click",()=>{this.resetSession()})}initializeUI(){document.getElementById("autoStartToggle").checked=this.config.autoStart,document.getElementById("stealthModeToggle").checked=this.config.stealthMode,document.getElementById("personalitySelect").value=this.config.personalityType,document.getElementById("maxPostsInput").value=this.config.maxPostsPerSession,document.getElementById("readingTimeMin").value=this.config.readingTimeRange.min,document.getElementById("readingTimeMax").value=this.config.readingTimeRange.max,this.updateStatus("Initializing...","initializing")}startRealTimeUpdates(){this.updateInterval=setInterval(()=>{this.updateSessionData(),this.updateActivityLog()},2e3),this.updateSessionData()}async updateSessionData(){try{const t=await chrome.runtime.sendMessage({action:"getSessionData"});if(t&&t.sessionData){const e=t.sessionData;document.getElementById("postsReadValue").textContent=e.postsRead||0,document.getElementById("adClicksValue").textContent=e.adClicks||0,document.getElementById("sessionTimeValue").textContent=this.formatDuration(e.startTime),document.getElementById("riskLevelValue").textContent=this.capitalizeFirst(e.riskLevel||"low"),this.updateProgressBars(e),this.updateStatusFromData(e)}}catch(t){}}updateProgressBars(t){const e=this.config.maxPostsPerSession,i=Math.min((t.postsRead||0)/e*100,100),s=Math.min((t.adClicks||0)/1*100,100);document.getElementById("postsProgressFill").style.width=`${i}%`,document.getElementById("clicksProgressFill").style.width=`${s}%`,document.getElementById("postsProgressText").textContent=`${t.postsRead||0}/${e}`,document.getElementById("clicksProgressText").textContent=`${t.adClicks||0}/1`}updateStatusFromData(t){t.startTime?this.updateStatus("Active","active"):this.updateStatus("Inactive","inactive")}async updateActivityLog(){try{const t=await chrome.runtime.sendMessage({action:"getActivityLog"});t&&t.activities&&this.displayActivityLog(t.activities)}catch(t){}}displayActivityLog(t){const e=document.getElementById("activityLog");if(!t||0===t.length)return void(e.innerHTML='\n                <div class="activity-item">\n                    <span class="activity-time">--:--</span>\n                    <span class="activity-text">Waiting for activity...</span>\n                </div>\n            ');const i=t.slice(-5);e.innerHTML=i.map(t=>`\n            <div class="activity-item fade-in">\n                <span class="activity-time">${this.formatTime(t.timestamp)}</span>\n                <span class="activity-text">${t.message}</span>\n            </div>\n        `).join(""),e.scrollTop=e.scrollHeight}async startAutomation(){try{this.updateStatus("Starting...","starting");const t=await chrome.runtime.sendMessage({action:"startAutomation"});t&&"started"===t.status?(this.updateStatus("Active","active"),this.updateButtonStates(!0),this.addActivityLog("Automation started")):(this.updateStatus("Failed to start","error"),this.showError("Failed to start automation"))}catch(t){this.updateStatus("Error","error"),this.showError("Failed to start automation")}}async stopAutomation(){try{this.updateStatus("Stopping...","stopping");const t=await chrome.runtime.sendMessage({action:"stopAutomation"});t&&"stopped"===t.status?(this.updateStatus("Inactive","inactive"),this.updateButtonStates(!1),this.addActivityLog("Automation stopped")):(this.updateStatus("Failed to stop","error"),this.showError("Failed to stop automation"))}catch(t){this.updateStatus("Error","error"),this.showError("Failed to stop automation")}}async exportData(){try{const t=await chrome.runtime.sendMessage({action:"exportSessionData"});if(t&&t.data){const e=JSON.stringify(t.data,null,2),i=new Blob([e],{type:"application/json"}),s=URL.createObjectURL(i),a=document.createElement("a");a.href=s,a.download=`smart-adsense-session-${Date.now()}.json`,a.click(),URL.revokeObjectURL(s),this.addActivityLog("Session data exported")}}catch(t){this.showError("Failed to export data")}}async resetSession(){try{const t=await chrome.runtime.sendMessage({action:"resetSession"});t&&"reset"===t.status?(this.updateSessionData(),this.addActivityLog("Session reset")):this.showError("Failed to reset session")}catch(t){this.showError("Failed to reset session")}}async saveConfig(){try{await chrome.runtime.sendMessage({action:"updateConfig",config:this.config})}catch(t){}}updateStatus(t,e){const i=document.getElementById("statusText"),s=document.getElementById("statusDot");i.textContent=t,s.classList.remove("active","inactive","starting","stopping","error"),e&&s.classList.add(e)}updateButtonStates(t){const e=document.getElementById("startBtn"),i=document.getElementById("stopBtn");e.disabled=t,i.disabled=!t}addActivityLog(t){const e=document.getElementById("activityLog"),i=document.createElement("div");for(i.className="activity-item fade-in",i.innerHTML=`\n            <span class="activity-time">${this.formatTime(Date.now())}</span>\n            <span class="activity-text">${t}</span>\n        `,e.appendChild(i);e.children.length>10;)e.removeChild(e.firstChild);e.scrollTop=e.scrollHeight}showError(t){this.addActivityLog(`Error: ${t}`),this.updateStatus("Error","error")}formatTime(t){return new Date(t).toLocaleTimeString("en-US",{hour12:!1,hour:"2-digit",minute:"2-digit"})}formatDuration(t){if(!t)return"0m 0s";const e=Date.now()-t;return`${Math.floor(e/6e4)}m ${Math.floor(e%6e4/1e3)}s`}capitalizeFirst(t){return t.charAt(0).toUpperCase()+t.slice(1)}cleanup(){this.updateInterval&&clearInterval(this.updateInterval)}}document.addEventListener("DOMContentLoaded",()=>{const t=new SmartAdSensePopup;window.addEventListener("beforeunload",()=>{t.cleanup()})})})();